"""Package independently verified sitting and leaning results without changing them."""
import csv,hashlib,html,json,shutil
from pathlib import Path
ROOT=Path('/data/humanoid-sitting-perception/contact_effort_repair_01');out=ROOT/'final_export_01';out.mkdir(exist_ok=False)
def read(p):return json.loads(p.read_text())
def rows(p):return list(csv.DictReader(p.open()))
def verify_manifest(folder):
    manifest=read(folder/'SHA256.json')
    for name,h in manifest.items():assert hashlib.sha256((folder/name).read_bytes()).hexdigest()==h,name
    return len(manifest)
checks={}
for task in ['sitting','leaning']:
    source=ROOT/(task+'_export_01');checks[task]=verify_manifest(source);assert read(source/'verification.json')['passed'];shutil.copytree(source,out/(task+'_results'))
diag=out/'diagnosis';shutil.copytree(ROOT/'diagnosis_report_02',diag);shutil.copytree(ROOT/'postcontact_unloading_probe_01_review',diag/'unloading_probe')
for name in ['leaning_rest_diagnosis.json','masked_advantage_momentum_diagnostic.json']:
    shutil.copy2(ROOT/name,diag/name)
shutil.copy2('/home/kadir/humanoid-sitting/docs/CONTACT_EFFORT_REPAIR_DIAGNOSIS.md',diag/'CONTACT_EFFORT_REPAIR_DIAGNOSIS.md')
sit=rows(out/'sitting_results/summary.csv');counts=rows(out/'sitting_results/counts.csv');lean=rows(out/'leaning_results/summary.csv')
def sm(policy,base,window='metrics_whole_trial'):
    return next(x for x in sit if x['bank']=='holdout' and x['policy']==policy and x['baseline']==base and x['window']==window and x['metric']=='total_squared_torque_Nm2')
def lm(seed,base,window='metrics_whole_trial'):
    return next(x for x in lean if x['bank']=='holdout' and x['seed']==str(seed) and x['baseline']==base and x['window']==window and x['metric']=='total_squared_torque_Nm2')
def pct(v):return f'{float(v):+.2f}%' if v not in [None,''] else 'N/A'
def count(name):return next(x for x in counts if x['bank']=='holdout' and x['policy']==name)
headlines=[]
for seed in [56211,56217]:
    c=count('final_'+str(seed));ref=sm('final_'+str(seed),'repaired_reference');parent=sm('final_'+str(seed),'repaired_parent_55211');last=sm('final_'+str(seed),'repaired_reference','metrics_last5s')
    headlines.append(dict(task='Sitting',seed=seed,successes=int(c['successes']),count=int(c['count']),physical_failures=int(c['physical_failures']),common_successes=int(ref['common_successes']),reference='Repaired reference',whole_reference_pct=float(ref['change_pct']) if ref['change_pct'] else None,whole_parent_pct=float(parent['change_pct']) if parent['change_pct'] else None,final5_reference_pct=float(last['change_pct']) if last['change_pct'] else None))
for seed in [56111,56117]:
    ref=lm(seed,'corrected_reference');parent=lm(seed,'starting_policy');last=lm(seed,'corrected_reference','metrics_last5s')
    headlines.append(dict(task='Leaning',seed=seed,successes=int(ref['successes']),count=int(ref['count']),physical_failures=int(ref['physical_failures']),common_successes=int(ref['common_successes']),reference='Corrected reference',whole_reference_pct=float(ref['change_pct']) if ref['change_pct'] else None,whole_parent_pct=float(parent['change_pct']) if parent['change_pct'] else None,final5_reference_pct=float(last['change_pct']) if last['change_pct'] else None))
old=count('old_reference');repair=count('repaired_reference');cost=sm('repaired_reference','old_reference');cost5=sm('repaired_reference','old_reference','metrics_last5s')
def table(headers,rs):return '<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rs)+'</table>'
doc='''<!doctype html><html><meta charset="utf-8"><title>Contact repair and effort PPO: final comparison</title><style>body{font:17px/1.55 system-ui;max-width:1160px;margin:38px auto;padding:0 24px;color:#20333b}h1{font-size:32px;line-height:1.2}h2{font-size:23px;margin-top:30px}table{border-collapse:collapse;font-size:14px;width:100%}th,td{padding:10px 7px;border-bottom:1px solid #cbd6d9;text-align:left}img{width:100%}.callout{padding:16px 22px;background:#eef5f4;border-left:4px solid #247d79}.caveat{padding:14px 22px;background:#faf4e9;border-left:4px solid #bd8536}a{color:#146a78}.links{display:flex;gap:24px;flex-wrap:wrap;font-weight:600}</style><h1>Contact repair and effort PPO: final comparison</h1><p>Standing-to-sitting and standing-to-leaning, tested separately on reserved nearby heights and slopes. Both small training comparisons and independent validation are complete. No policy has been promoted.</p>'''
doc+=f'<div class="callout"><b>Sitting contact repair:</b> reserved-surface success changes from {old["successes"]}/{old["count"]} for the old corrected reference to {repair["successes"]}/{repair["count"]} for the repaired reference. Physical failures change from {old["physical_failures"]} to {repair["physical_failures"]}. The learned adjustments are evaluated separately below.</div>'
doc+='<h2>Full-budget final policies on reserved surfaces</h2>'+table(['Task / seed','Stable trials','Physical failures','Whole-motion effort vs reference','Whole-motion effort vs starting policy','Final 5 s effort vs reference','Common successes'],[[f"{r['task']} {r['seed']}",f"{r['successes']}/{r['count']}",r['physical_failures'],pct(r['whole_reference_pct']),pct(r['whole_parent_pct']),pct(r['final5_reference_pct']),r['common_successes']] for r in headlines])
doc+='<p>Effort here means the sum of squared physical joint torques over all 37 joints. Sitting uses the newly repaired reference and the repaired 55211 starting policy; leaning uses the existing corrected reference and each seed’s own starting policy. Negative values mean less effort. Comparisons include only trials where both methods succeed for the full 20 seconds. Failures remain counted above.</p>'
doc+=f'<div class="caveat"><b>Safer sitting is still costly.</b> On the {cost["common_successes"]} unseen trials also completed by the old reference, the repair changes whole-motion effort by {pct(cost["change_pct"])} and final 5 s effort by {pct(cost5["change_pct"])}. Do not confuse a PPO saving relative to the repair with beating the old successful posture. The robot still carries much of its weight through its feet.</div>'
doc+='<p><b>Leaning remains inconsistent:</b>56111 lowers effort and retains16/16 stable trials;56117 retains only2/16 and is rejected in favor of its unchanged parent. Its knee/ankle adjustments increase tangential support demand and exceed the friction safety margin without a fall or visible slip. One successful run is not a repeatable two-seed result.</p>'
doc+='<div class="links"><a href="sitting_results/findings.html">Sitting report and all baselines</a><a href="sitting_results/motion_replay.html">Sitting motion replay</a><a href="leaning_results/findings.html">Leaning report</a><a href="diagnosis/CONTACT_EFFORT_REPAIR_DIAGNOSIS.md">Diagnosis and limitations</a></div>'
doc+='<h2>What changed</h2><p>The sitting repair uses the observed seat plane, joint encoders and IMU to transfer the pelvis above the seat before lowering, with foot-preserving inverse kinematics and ankle balance feedback. The new PPO learns two coordinated knee/hip/ankle adjustments held 200 ms after 12 seconds. Approach traces remain exactly identical to the corresponding repaired starting policy. Simulator truth supplies reward and validation labels only, not runtime control.</p>'
doc+='<p>The earlier leaning training increased effort through worse leg posture. Prescribed coordinated perturbations confirmed that lower-effort stable poses exist. Slower coordinated PPO found an improvement in one run; the other moved in a worse direction. A separate diagnostic also found that masking actor advantages does not fully freeze Adam momentum updates. It is recorded as a future optimizer correction, not silently changed in these frozen studies or claimed as the sole cause.</p>'
doc+='<h2>The remaining physical problem</h2><p>A separate prescribed continuation transferred more weight onto the seat and lowered effort in8/9 development cases, but introduced an unwanted contact in the ninth. It is not validated for use and was excluded from PPO training/selection. The next physical objective is a legal resting posture that transfers much more weight away from the feet.</p><img src="diagnosis/unloading_probe/comparison.png" alt="Exploratory reference-only unloading; neither candidate passes the complete development grid">'
doc+='<p><b>Validation:</b> each task has two child runs,115,200 physical transitions per run, including indexed-reset warmup. Leaning also has a separate 46,080-transition preflight; sitting preflight used no learning. Independent verifiers check frozen/prior hashes, exact checkpoint loads and starts, finite changed weights, complete20s horizons, budgets, fixed fingers, bounded commands and selection before holdout. Sitting paths are rebuilt independently from saved sensor inputs. Execution-only leaning recovery is preserved and documented in its report.</p>'
doc+='<p><b>Scope:</b> each task uses eight reserved geometries repeated twice. These are nearby rigid slabs with reference assistance and known horizontal placement, not arbitrary furniture. The two leaning seeds use different frozen parents; both sitting seeds use the same validated parent. Torque is a proxy, not electrical energy or proof of a global optimum. The detailed reports include absolute torque, RMS Nm, leg/upper-body torque, seat/foot load, per-height/slope outcomes and geometry-error audits.</p></html>'
(out/'findings.html').write_text(doc);(out/'headline_results.json').write_text(json.dumps(dict(results=headlines,source_manifest_counts=checks),indent=2));shutil.copy2(__file__,out/'combine_source.py')
(out/'SHA256.json').write_text(json.dumps({str(p.relative_to(out)):hashlib.sha256(p.read_bytes()).hexdigest() for p in out.rglob('*') if p.is_file()},indent=2));print(out)
